\section{The model}

\subsection{Pantries, dishes, tasters}

\begin{definition}[Pantry, dish]
For $n\in\mathbb N$, a \emph{pantry} is a vector $x\in\{0,1\}^n$. A \emph{dish} is a function
$f:\{0,1\}^n\to\{0,1\}$.
\end{definition}

\begin{definition}[Tasting strategy]
A \emph{tasting strategy} (or \emph{taster}) on $n$ ingredients is a finite binary tree generated by
\[
T ::= \serve(b) \;\mid\; \probe(i,\,T_0,\,T_1), \qquad b\in\{0,1\},\ i\in\{1,\dots,n\}.
\]
Its \emph{depth} is $\dep(\serve(b))=0$ and $\dep(\probe(i,T_0,T_1))=1+\max(\dep T_0,\dep T_1)$. Its
\emph{evaluation} is $\ev(\serve(b),x)=b$ and $\ev(\probe(i,T_0,T_1),x)=\ev(T_{x_i},x)$. Its
\emph{path} at $x$ is $\pathop(\serve(b),x)=\varnothing$ and
$\pathop(\probe(i,T_0,T_1),x)=\{i\}\cup\pathop(T_{x_i},x)$. We say $T$ \emph{computes} $f$ if
$\ev(T,x)=f(x)$ for all $x$.
\end{definition}

\begin{definition}[Cooking and verification time]
For a dish $f$ on $n$ ingredients, $C(f):=n$ and $V(f):=\min\{\dep(T): T\text{ computes }f\}$. The
minimum is attained; a minimiser is called an \emph{optimal taster}. $V$ is the usual deterministic
query complexity, also written $D$.
\end{definition}

\subsection{The path lemma}

\begin{lemma}[Path lemma, part 1]\label{lem:path1}
For every taster $T$ and pantry $x$, $|\pathop(T,x)|\le\dep(T)$.
\end{lemma}

\begin{proof}
Induction on $T$. A leaf probes nothing. At $\probe(i,T_0,T_1)$ the path is $\{i\}$ together with the
path of the taken subtree, so its size is at most $1+\max_b|\pathop(T_b,x)|\le
1+\max_b\dep(T_b)=\dep(T)$.
\end{proof}

\begin{lemma}[Path lemma, part 2]\label{lem:path2}
If $y_i=x_i$ for every $i\in\pathop(T,x)$, then $\ev(T,y)=\ev(T,x)$.
\end{lemma}

\begin{proof}
Induction on $T$. At $\probe(i,T_0,T_1)$ we have $i\in\pathop(T,x)$, so $y_i=x_i$ and both
evaluations descend into the same subtree; the remaining path agreement is exactly the inductive
hypothesis for that subtree.
\end{proof}

Together: a taster sees at most $\dep$ ingredients, and its verdict is a function of what it saw.
Every lower bound below is an application of Lemma~\ref{lem:path2}.

\subsection{Brute force}

\begin{definition}[Exhaustive taster]
Fix a default pantry $a$. Set $B_0(a):=\serve(f(a))$ and, for $k<n$,
$B_{k+1}(a):=\probe\big(k,\,B_k(a[k\mapsto0]),\,B_k(a[k\mapsto1])\big)$.
\end{definition}

\begin{lemma}\label{lem:brute}
$\dep(B_k(a))\le k$ and $\ev(B_k(a),x)=f\big(j\mapsto \text{if } j<k \text{ then } x_j \text{ else } a_j\big)$.
\end{lemma}

\begin{theorem}[Tasting never exceeds cooking]\label{thm:VleC}
$V(f)\le C(f)=n$ for every dish $f$.
\end{theorem}

\begin{proof}
$B_n(a)$ has depth at most $n$ and, by Lemma~\ref{lem:brute} with $k=n$, evaluates to $f(x)$ for
every $x$.
\end{proof}

\section{Sensitivity: the universal lower bound}

\begin{definition}[Pivotal ingredient, sensitivity]
Ingredient $i$ is \emph{pivotal} for $f$ at $x$ if $f(x^{\oplus i})\ne f(x)$, where $x^{\oplus i}$ is
$x$ with coordinate $i$ flipped. Put $\piv(f,x):=\{i:i\text{ pivotal at }x\}$ and
$s(f,x):=|\piv(f,x)|$.
\end{definition}

\begin{theorem}[Pivotal ingredients must be probed]\label{thm:pivpath}
If $T$ computes $f$ and $i$ is pivotal at $x$, then $i\in\pathop(T,x)$.
\end{theorem}

\begin{proof}
Suppose not, and put $y:=x^{\oplus i}$. Then $y$ agrees with $x$ on all of $\pathop(T,x)$, since the
only disagreement is at $i\notin\pathop(T,x)$. By Lemma~\ref{lem:path2}, $\ev(T,y)=\ev(T,x)$, hence
$f(y)=f(x)$, contradicting pivotality.
\end{proof}

\begin{corollary}[Sensitivity lower bound]\label{cor:sens}
$s(f,x)\le V(f)$ for every dish $f$ and pantry $x$.
\end{corollary}

\begin{proof}
Take an optimal taster $T$. By Theorem~\ref{thm:pivpath}, $\piv(f,x)\subseteq\pathop(T,x)$, and by
Lemma~\ref{lem:path1}, $|\pathop(T,x)|\le\dep(T)=V(f)$.
\end{proof}

\begin{theorem}[Zero-probe verdicts]\label{thm:zero}
$V(f)=0$ if and only if $f$ is constant.
\end{theorem}

\begin{proof}
If $V(f)=0$ the optimal taster is a leaf $\serve(b)$, so $f\equiv b$. Conversely a constant is
computed by a leaf.
\end{proof}

In culinary terms: you cannot judge a dish without tasting it, unless its quality was decided before
you started cooking.

\section{Three model dishes}

\subsection{Salad: the dictator}

\begin{definition}
The \emph{salad} is $\sal_i(x):=x_i$.
\end{definition}

\begin{proposition}\label{prop:salad}
$V(\sal_i)=1$, so $C/V=n$.
\end{proposition}

\begin{proof}
The taster $\probe(i,\serve(0),\serve(1))$ computes it with depth $1$; the dish is not constant, so
by Theorem~\ref{thm:zero} its cost is not $0$.
\end{proof}

\subsection{The spoiled-ingredient dish and the kitchen separation}

\begin{definition}
$\spoiled(x):=1$ iff $x_i=1$ for some $i$ (the OR function; $x_i=1$ encodes ``ingredient $i$ is
spoiled'').
\end{definition}

\begin{definition}[Certificate]
A set $S\subseteq\{1,\dots,n\}$ is a \emph{certificate} for $f$ at $x$ if every $y$ agreeing with $x$
on $S$ satisfies $f(y)=f(x)$. Let $C_1(f)$ and $C_0(f)$ be the maxima over $1$-inputs and $0$-inputs
of the least certificate size.
\end{definition}

\begin{proposition}[Nondeterminism is at least as fast]\label{prop:certfromtree}
For every $f$ and $x$ there is a certificate of size at most $V(f)$, namely $\pathop(T,x)$ for an
optimal taster $T$.
\end{proposition}

\begin{proof}
By Lemma~\ref{lem:path2}, any $y$ agreeing with $x$ on $\pathop(T,x)$ has
$f(y)=\ev(T,y)=\ev(T,x)=f(x)$; the size bound is Lemma~\ref{lem:path1}.
\end{proof}

\begin{proposition}[Certificates contain pivotal ingredients]\label{prop:pivcert}
If $S$ is a certificate for $f$ at $x$, then $\piv(f,x)\subseteq S$.
\end{proposition}

\begin{proof}
If $i\notin S$ were pivotal, then $x^{\oplus i}$ agrees with $x$ on $S$, so $f(x^{\oplus i})=f(x)$,
a contradiction.
\end{proof}

\begin{proposition}\label{prop:orcert}
If $x_i=1$ then $\{i\}$ is a certificate for $\spoiled$ at $x$. At the all-fresh pantry $\mathbf0$
every ingredient is pivotal.
\end{proposition}

\begin{theorem}\label{thm:or}
$V(\spoiled)=n$.
\end{theorem}

\begin{proof}
``$\le$'' is Theorem~\ref{thm:VleC}; ``$\ge$'' is Corollary~\ref{cor:sens} at $\mathbf0$, where the
sensitivity is $n$ by Proposition~\ref{prop:orcert}.
\end{proof}

\begin{theorem}[Kitchen $\Pclass\ne\NP$, unconditional]\label{thm:PneNP}
Let $n\ge2$. At every pantry with $\spoiled(x)=1$ there is a certificate of size exactly $1$, while
every deterministic taster for $\spoiled$ needs $n$ probes. Hence
$1=C_1(\spoiled)<V(\spoiled)=n$.
\end{theorem}

\begin{proof}
Combine Proposition~\ref{prop:orcert} with Theorem~\ref{thm:or}.
\end{proof}

Unlike the Turing-machine statement, this is a theorem: a hint --- a garnish pointing at the guilty
ingredient --- compresses verification from $n$ probes to one, and the gap is unbounded in $n$.

\subsection{The soufflé: parity, hard from both sides}

\begin{definition}
The \emph{soufflé} is $\souf(x):=\bigoplus_i x_i$: it rises exactly when an odd number of the $n$
critical steps went right.
\end{definition}

\begin{lemma}\label{lem:parflip}
For every $x$ and $i$, $\souf(x^{\oplus i})\ne\souf(x)$.
\end{lemma}

\begin{proof}
Split $\sum_j x_j = x_i + \sum_{j\ne i}x_j$; flipping $x_i$ changes the first summand by $\pm1$ and
leaves the second fixed, hence changes the parity.
\end{proof}

\begin{theorem}[Evasiveness of the soufflé]\label{thm:soufevasive}
$\piv(\souf,x)=\{1,\dots,n\}$ for every $x$, and hence $V(\souf)=n=C(\souf)$.
\end{theorem}

\begin{theorem}[Soufflé Theorem: no nondeterministic shortcut]\label{thm:souf}
Every certificate for $\souf$ at every pantry is the whole ingredient set; consequently
$C_0(\souf)=C_1(\souf)=n$.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:pivcert} a certificate contains $\piv(\souf,x)=\{1,\dots,n\}$, and it is a
subset of $\{1,\dots,n\}$.
\end{proof}

This is the defensible replacement for the informal ``soufflé verification is $\coNP$-hard'' claim:
no thermodynamic input is needed, and the honest combinatorial content is that the soufflé is hard
to verify from \emph{both} sides, unlike the spoiled-ingredient dish, which is easy from one.

\begin{corollary}
For $n\ge2$, $V(\sal_i)=1<n=V(\souf)=C(\souf)$.
\end{corollary}

\section{The spectrum, and the inversion of the conjecture}

\begin{definition}[Supported parity]
For $S\subseteq\{1,\dots,n\}$ let $\parity_S(x):=\bigoplus_{j\in S}x_j$, and write
$f_k:=\parity_{\{1,\dots,k\}}$.
\end{definition}

\begin{lemma}\label{lem:pivpar}
$\piv(\parity_S,x)=S$ for every $x$.
\end{lemma}

\begin{proof}
For $i\in S$, flipping $x_i$ flips the parity of the $S$-sum (as in Lemma~\ref{lem:parflip}). For
$i\notin S$ the $S$-sum, hence the verdict, is unchanged.
\end{proof}

\begin{theorem}[Spectrum Theorem]\label{thm:spectrum}
For every $k\le n$, $V(f_k)=k$. Hence every value in $\{0,1,\dots,n\}$ is the exact verification cost
of some dish on $n$ ingredients, and every ratio $C/V=n/k$ with $1\le k\le n$ is realised by an
actual dish.
\end{theorem}

\begin{proof}
Upper bound: $f_k$ depends only on the first $k$ coordinates, so the truncated exhaustive taster
$B_k$ computes it in $k$ probes. Lower bound: Lemma~\ref{lem:pivpar} gives sensitivity exactly $k$ at
every pantry, and Corollary~\ref{cor:sens} applies.
\end{proof}

\begin{definition}
For non-constant $f$ put $\rho(f):=C(f)/V(f)\in\mathbb Q$. Call $f$ \emph{evasive} if $V(f)=n$.
\end{definition}

\begin{theorem}[Inversion Theorem]\label{thm:inv}
For non-constant $f$, $\rho(f)=1$ if and only if $f$ is evasive.
\end{theorem}

\begin{proof}
$\rho(f)=1$ iff $C(f)=V(f)$ iff $V(f)=n$, using $V(f)>0$ (Theorem~\ref{thm:zero}).
\end{proof}

This contradicts the naive conjecture in the strongest possible way: the informal claim was that
``quick recipes have $C=V$ while hard recipes have $C\gg V$'', whereas in truth $C=V$ characterises
the maximally hard dishes, and the easiest non-trivial dish, the salad, attains the extreme ratio
$\rho=n$ (Proposition~\ref{prop:salad}). The source of the confusion is a conflation of
\emph{absolute} difficulty with \emph{relative discount}: $\rho$ measures how much verification saves
you, and hard dishes offer no saving.

\begin{theorem}[Menu Rigidity]\label{thm:menu}
Let $(f_\iota)_{\iota\in I}$ be a non-empty finite family of non-constant dishes on $n$ ingredients,
with aggregate ratio $\rho_{\mathrm{agg}}:=\sum_\iota C(f_\iota)\big/\sum_\iota V(f_\iota)$. Then
$\rho_{\mathrm{agg}}=1$ if and only if $V(f_\iota)=n$ for every $\iota$.
\end{theorem}

\begin{proof}
Each dish satisfies $0<V(f_\iota)\le C(f_\iota)$ (Theorems~\ref{thm:zero} and~\ref{thm:VleC}), so
$\sum V\le\sum C$ with equality iff $V(f_\iota)=C(f_\iota)$ termwise. Apply Theorem~\ref{thm:inv}
termwise.
\end{proof}

\subsection{A census of one hundred recipes}

Take $n=100$ ingredients and the hundred dishes $f_1,\dots,f_{100}$.

\begin{proposition}
Recipe $k$ has $C=100$ and $V=k$, hence $\rho=100/k$; the ratios sweep the full range from $100$ (the
one-probe dish $f_1$) down to $1$ (the evasive dish $f_{100}$).
\end{proposition}

\begin{theorem}[Census]
The aggregate cook time is $100\cdot100=10000$, the aggregate taste time is $\sum_{k=1}^{100}k=5050$,
and therefore
\[
\rho_{\mathrm{agg}}=\frac{10000}{5050}=\frac{200}{101}\approx1.980 .
\]
\end{theorem}

The mean of the individual ratios is $\frac1{100}\sum_k 100/k\approx5.19$, very far from the
aggregate. Aggregation weights dishes by their verification load, so hard dishes dominate: a
restaurant whose menu includes soufflés is nearly break-even no matter how many salads it serves.

\section{Almost every recipe is a soufflé}

\begin{theorem}[One-probe classification]\label{thm:class1}
If $V(f)\le1$ then $f$ is constant, a dictator $x\mapsto x_i$, or a negated dictator
$x\mapsto\lnot x_i$.
\end{theorem}

\begin{proof}
An optimal taster of depth $\le1$ is either a leaf (constant) or $\probe(i,\serve(a),\serve(c))$, so
$f(x)=$ if $x_i$ then $c$ else $a$. The four choices of $(a,c)$ give the two constants, the dictator
and the negated dictator.
\end{proof}

\begin{corollary}
At most $2n+2$ dishes on $n$ ingredients satisfy $V\le1$. Since there are $2^{2^n}$ dishes in total
and $2n+2<2^{2^n}$ for $n\ge2$, quick recipes are rare, with a doubly exponential gap.
\end{corollary}

Let $c_d:=\#\{f:\{0,1\}^n\to\{0,1\} \mid V(f)\le d\}$.

\begin{theorem}[Structure of $(d{+}1)$-quick dishes]\label{thm:struct}
If $V(f)\le d+1$, then either $f$ is constant, or there are an ingredient $i$ and dishes $g_0,g_1$
with $V(g_0),V(g_1)\le d$ and $f(x)=$ if $x_i$ then $g_1(x)$ else $g_0(x)$.
\end{theorem}

\begin{proof}
Take an optimal taster. If it is a leaf, $f$ is constant. Otherwise it is $\probe(i,T_0,T_1)$ with
both subtrees of depth $\le d$; take $g_b:=\ev(T_b,\cdot)$, computed by $T_b$, so $V(g_b)\le d$.
\end{proof}

\begin{corollary}[Counting recursion]
$c_0=2$ and $c_{d+1}\le2+n\,c_d^2$.
\end{corollary}

\begin{theorem}[Solving the recursion]\label{thm:count}
For $n\ge1$ and all $d$, $3n\,c_d\le(6n)^{2^d}$, hence $c_d\le(6n)^{2^d}$.
\end{theorem}

\begin{proof}
Induction on $d$. Base: $3n\cdot2=6n=(6n)^{2^0}$. Step, using $c_d\ge1$ and $n\le n^2c_d^2$:
\[
3n\,c_{d+1}\le 3n(2+nc_d^2)=6n+3n^2c_d^2\le 6n^2c_d^2+3n^2c_d^2=(3nc_d)^2\le\big((6n)^{2^d}\big)^2
=(6n)^{2^{d+1}} .\qedhere
\]
\end{proof}

\begin{theorem}[Existence of hard recipes]
If $n\ge1$ and $(6n)^{2^d}<2^{2^n}$, then some dish on $n$ ingredients has $V(f)>d$.
\end{theorem}

\begin{theorem}[Generic hardness]\label{thm:generic}
If $n\ge1$ and $2\,(6n)^{2^d}\le2^{2^n}$, then at least half of all dishes on $n$ ingredients have
$V(f)>d$.
\end{theorem}

\begin{corollary}
With $n=16$ ingredients, at least half of all $2^{65536}$ dishes require more than $7$ taste probes.
\end{corollary}

\begin{proof}
$(6\cdot16)^{2^7}=96^{128}\le(2^7)^{128}=2^{896}$, so $2\cdot96^{128}\le2^{897}\le2^{65536}=2^{2^{16}}$.
Apply Theorem~\ref{thm:generic}.
\end{proof}

The recipes we actually cook are drawn from a vanishingly thin, highly structured sliver of the space
of all conceivable dishes; a \emph{random} dish is a soufflé.

\section{Adaptivity: deciding what to taste next}

\begin{definition}[Nonadaptive checklist]
A set $S$ is a \emph{nonadaptive checklist} for $f$ if $S$ is a certificate for $f$ at \emph{every}
pantry.
\end{definition}

\begin{definition}[Relevant ingredient]
Ingredient $i$ is \emph{relevant} for $f$ if it is pivotal at some pantry; $\rel(f)$ denotes the set
of relevant ingredients.
\end{definition}

\begin{lemma}\label{lem:checklist}
Every nonadaptive checklist contains $\rel(f)$.
\end{lemma}

\begin{proof}
If $i$ is pivotal at $x$, then by Proposition~\ref{prop:pivcert} every certificate at $x$ contains
$i$; a checklist is in particular a certificate at $x$.
\end{proof}

\begin{definition}[Multiplexer]
On three ingredients --- sauce, fish, soup --- set $\mux(x):=$ if $x_{\text{sauce}}$ then
$x_{\text{fish}}$ else $x_{\text{soup}}$.
\end{definition}

\begin{proposition}\label{prop:mux}
$V(\mux)=2$ and $\rel(\mux)=\{\text{sauce},\text{fish},\text{soup}\}$.
\end{proposition}

\begin{proof}
Upper bound: probe the sauce, then the fish or the soup accordingly. Lower bound: at the pantry
(sauce $=1$, fish $=1$, soup $=0$) both the sauce and the fish are pivotal, so $s=2$ and
Corollary~\ref{cor:sens} applies. Relevance: the sauce and the fish are pivotal at that pantry, and
the soup is pivotal at (sauce $=0$, fish $=1$, soup $=0$).
\end{proof}

\begin{theorem}[Adaptivity Gap]
Every nonadaptive checklist for $\mux$ consists of all three ingredients, while an adaptive taster
needs only two probes.
\end{theorem}

\begin{proof}
Combine Lemma~\ref{lem:checklist} with Proposition~\ref{prop:mux}.
\end{proof}

\section{When both proofs are short: the product bound}

\begin{theorem}[Certificate overlap]\label{thm:overlap}
Let $S$ be a certificate for $f$ at $x$ and $T$ a certificate for $f$ at $y$, with $f(x)\ne f(y)$.
Then $S\cap T\ne\varnothing$.
\end{theorem}

\begin{proof}
Suppose $S\cap T=\varnothing$ and define the hybrid pantry $u_j:=x_j$ for $j\in S$ and $u_j:=y_j$
otherwise. Then $u$ agrees with $x$ on $S$, so $f(u)=f(x)$; and $u$ agrees with $y$ on $T$, since
$j\in T$ implies $j\notin S$, so $f(u)=f(y)$. Hence $f(x)=f(y)$, a contradiction.
\end{proof}

\begin{definition}[Restriction]
For a dish $f$, a set $S$ and a pantry $a$, put
$f|_{S\leftarrow a}(y):=f\big(j\mapsto \text{if } j\in S \text{ then } a_j \text{ else } y_j\big)$.
\end{definition}

\begin{lemma}[Certificates restrict]\label{lem:restrict}
If $T$ is a certificate for $f$ at the pantry $j\mapsto(\text{if }j\in S\text{ then }a_j\text{ else }z_j)$,
then $T\setminus S$ is a certificate for $f|_{S\leftarrow a}$ at $z$.
\end{lemma}

\begin{proof}
Any $y$ agreeing with $z$ on $T\setminus S$ yields a full pantry agreeing with the original one on
all of $T$, so the verdicts coincide.
\end{proof}

\begin{definition}[Checklist-then-continue taster]
For a list $L$ of ingredients, a continuation $\mathrm{cont}$ mapping accumulated knowledge to a
taster, and an accumulator $a$, define $\QL([\,],\mathrm{cont},a):=\mathrm{cont}(a)$ and
\[
\QL(i{::}L,\mathrm{cont},a):=\probe\big(i,\ \QL(L,\mathrm{cont},a[i\mapsto0]),\ \QL(L,\mathrm{cont},a[i\mapsto1])\big).
\]
\end{definition}

\begin{lemma}\label{lem:QL}
If every $\mathrm{cont}(a)$ has depth $\le d$, then $\dep(\QL(L,\mathrm{cont},a))\le|L|+d$, and
\[
\ev(\QL(L,\mathrm{cont},a),x)=\ev\big(\mathrm{cont}(j\mapsto\text{if } j\in L \text{ then } x_j \text{ else } a_j),\,x\big).
\]
\end{lemma}

\begin{theorem}[Certificate Product Theorem]\label{thm:product}
Suppose every $0$-input of $f$ has a certificate of size $\le k$ and every $1$-input a certificate of
size $\le m$. Then $V(f)\le k\cdot m$.
\end{theorem}

\begin{proof}
Induction on $k$.

\emph{Base $k=0$.} If $f$ has a $0$-input $x_0$, its certificate is $\varnothing$, so $f\equiv0$ and
$V(f)=0$ by Theorem~\ref{thm:zero}. If $f$ has no $0$-input, $f\equiv1$ and again $V(f)=0$.

\emph{Step $k\to k+1$.} If $f$ has no $1$-input it is constant and $V(f)=0$. Otherwise fix a $1$-input
$x_1$ with certificate $S$, $|S|\le m$, and consider any restriction $f|_{S\leftarrow a}$.

\emph{Badness budget drops.} Let $z$ be a $0$-input of the restriction, corresponding to a full
$0$-input $w$ of $f$, and let $T$ be a certificate for $f$ at $w$ with $|T|\le k+1$. Since
$f(x_1)=1\ne0=f(w)$, Theorem~\ref{thm:overlap} gives some $i\in S\cap T$. By
Lemma~\ref{lem:restrict}, $T\setminus S$ is a certificate for the restriction at $z$, and
$T\setminus S\subseteq T\setminus\{i\}$, whence $|T\setminus S|\le|T|-1\le k$.

\emph{Goodness budget survives.} Likewise $1$-inputs of the restriction inherit certificates
$T\setminus S$ of size $\le|T|\le m$.

By induction $V(f|_{S\leftarrow a})\le km$ for every $a$; choose optimal tasters $t_a$ of that depth.
The strategy $\QL(S,\,a\mapsto t_a,\,\mathbf0)$ --- probe all of $S$, then run the optimal taster for
the resulting restriction --- computes $f$ by Lemma~\ref{lem:QL} and has depth at most
$|S|+km\le m+km=(k+1)m$.
\end{proof}

\begin{corollary}[Squaring form]
If every input of $f$ has a certificate of size $\le c$, then $V(f)\le c^2$.
\end{corollary}

In the language of the metaphor: in the kitchen, $\NP\cap\coNP$ collapses into $\Pclass$, at the cost
of squaring the tasting time.

\begin{proposition}[Tightness]
For $\spoiled$ we have $C_1=1$ and $C_0=n$, and Theorem~\ref{thm:product} yields the bound
$1\cdot n=n$, which is exactly $V(\spoiled)$.
\end{proposition}

\begin{proposition}[Slack]
For $\souf$ we have $C_0=C_1=n$ (Theorem~\ref{thm:souf}), so the squaring form yields only
$V\le n^2$ while the truth is $V=n$: the theorem is powerless exactly where there is nothing to gain.
\end{proposition}

\section{Algorithms}

\textbf{(A) Exact verification cost by memoised restriction search.} Given the truth table of $f$,
compute
\[
V(f)=\begin{cases}0 & f\text{ constant},\\
1+\min_i\max\big(V(f|_{i\leftarrow0}),V(f|_{i\leftarrow1})\big) & \text{otherwise},\end{cases}
\]
whose correctness is Theorem~\ref{thm:struct} read as an equation. Memoising over restrictions gives
worst-case complexity $O(3^n\cdot n)$, practical up to $n\approx12$.

\textbf{(B) Sensitivity lower bound.} Compute $\max_x s(f,x)$ in $O(2^nn)$ by flipping each
coordinate at each pantry; by Corollary~\ref{cor:sens} this certifies a lower bound on $V(f)$, tight
for parity-type dishes.

\textbf{(C) Minimum certificate at a point.} Search subsets in increasing size, testing the defining
condition; Proposition~\ref{prop:pivcert} prunes the search, since every candidate must contain
$\piv(f,x)$.

\textbf{(D) The product-bound taster.} Repeatedly pick a $1$-input consistent with what has been
seen, probe its whole certificate, and recurse on the restriction. Each round costs at most $C_1$
probes and lowers the badness budget by one, so the strategy terminates within $C_0C_1$ probes.

\section{Discussion}

\subsection{What the model buys, and what it costs}

The decision-tree model was chosen because it is the largest natural model in which the intended
separations are unconditional. The price is that it is very weak: cooking is a single number $n$;
there is no notion of an ingredient's preparation cost, of sequencing, of parallel burners, or of
destructive measurement.

The most conspicuous absence is \emph{destructiveness}. Cutting a soufflé to check whether it rose
destroys the soufflé; probing a coordinate does not. Theorem~\ref{thm:souf} captures the
\emph{informational} half of that predicament (no partial probe tells you anything) but not the
\emph{physical} half. A model with consumable probes --- each ingredient may be tasted at most once,
and tasting reduces the dish --- would be the natural next formalism.

\subsection{The claim we deliberately did not prove}

We do not claim that soufflé verification is $\coNP$-hard by reduction to Navier--Stokes simulation.
Such a statement needs a physical model, a discretisation with a stated error budget, and an actual
reduction. What we prove instead is the exact combinatorial shadow of the claim: the soufflé's
certificate complexity is maximal on both sides, so it is hard to verify in the strongest sense the
model can express. We regard this substitution --- a defensible theorem in place of an indefensible
one --- as the main methodological point of the work.

\subsection{The inverted conjecture as a case study}

The originating conjecture (``quick recipes have $C=V$, hard recipes have $C\gg V$'') is false, with
the inequality exactly reversed (Theorem~\ref{thm:inv}). The intuition was about \emph{absolute}
effort, the formalism about \emph{relative} discount, and the two run in opposite directions.
Precise definitions earn their keep precisely in cases like this.

\section{Future directions}

\begin{conjecture}[Sensitivity--tasting polynomial equivalence]
For every dish $f$, $V(f)\le\big(\max_x s(f,x)\big)^4$.
\end{conjecture}
The sensitivity lower bound would then be not merely a bound but polynomially tight: a cook who can
find a pivotal ingredient at every pantry can always design a fast tasting protocol. The product
bound is one leg of the standard chain from sensitivity to query complexity; the missing layer is
block sensitivity.

\begin{conjecture}[Evasiveness of monotone kitchen properties]
Every non-constant monotone dish invariant under a transitive group of ingredient permutations is
evasive: $V(f)=n$.
\end{conjecture}
Culinary symmetry --- no ingredient plays a distinguished role --- is exactly the hypothesis of the
classical evasiveness theorem for transitive monotone properties, so the kitchen intuition ``you must
check everything in a symmetric recipe'' should be a theorem.

\begin{conjecture}[Randomised tasting saves at most a cubic factor]
$V(f)\le O\big(R(f)^3\big)$, where $R$ is the bounded-error randomised query complexity.
\end{conjecture}
Guessing where to taste would then be worth at most a polynomial saving.

Two further programmes: a \emph{destructive-probe model}, in which probes consume the dish, capturing
the specifically culinary phenomenon that the soufflé theorem only half-captures; and
\emph{cost-weighted cooking}, replacing $C(f)=n$ by $C(f)=\sum_iw_i$ for ingredient-dependent
preparation costs, turning the spectrum theorem into a statement about weighted ratios.

\section{Conclusion}

Fixing a computational model turns the recipe metaphor into mathematics, and the mathematics is
richer than the metaphor. Tasting is never harder than cooking; sensitivity is a universal lower
bound; the spoiled-ingredient dish separates deterministic from nondeterministic verification
unconditionally; the soufflé resists certification from both sides; the whole spectrum of cook/taste
ratios is realised; break-even recipes are the \emph{hardest} ones, not the easiest, inverting the
naive conjecture; almost every conceivable dish is a soufflé; adaptivity is strictly powerful; and a
dish with short proofs on both sides is quick to taste outright, up to a product.

The one claim the model refuses to underwrite --- that soufflé verification is hard for thermodynamic
reasons --- is replaced by one it does: that the soufflé is hard for combinatorial reasons, in the
strongest sense the model can state.

\end{document}

