"""
Exhaustive Atlas of All Dishes on Three Ingredients
===================================================

There are 2^(2^3) = 256 distinct dishes on a pantry of three ingredients.  This
script enumerates every one of them and tabulates, exactly:

  * V   -- the deterministic tasting cost (minimum worst-case number of probes);
  * s   -- the maximal sensitivity (number of pivotal ingredients at the worst
           pantry), which is a certified lower bound on V;
  * C0  -- the worst-case size of a shortest proof of badness;
  * C1  -- the worst-case size of a shortest proof of goodness.

It then verifies, over the entire population of dishes, the five structural
theorems of the theory:

  (i)   V <= n                       tasting never costs more than cooking;
  (ii)  s <= V                       sensitivity is a lower bound;
  (iii) max(C0, C1) <= V             nondeterminism is at least as fast;
  (iv)  V <= C0 * C1                 the certificate product bound;
  (v)   V <= 1 iff the dish is a constant, a dictator, or a negated dictator,
        of which there are exactly 2n + 2 = 8.

Finally it prints the exact population distribution of V, exhibiting the
'almost every recipe is a souffle' phenomenon already at n = 3: 194 of the 256
dishes (76%) are evasive, requiring all three probes.

Self-contained: standard library only.
"""

from __future__ import annotations

from collections import Counter
from functools import lru_cache
from itertools import combinations, product
from typing import Dict, FrozenSet, List, Sequence, Tuple

N = 3
PANTRIES: List[Tuple[int, ...]] = [tuple(p) for p in product((0, 1), repeat=N)]
INDEX: Dict[Tuple[int, ...], int] = {x: i for i, x in enumerate(PANTRIES)}


def taste_cost(table: Tuple[int, ...]) -> int:
    """Exact V(f) via V(f) = 1 + min_i max(V(f|i=0), V(f|i=1))."""

    @lru_cache(maxsize=None)
    def rec(tab: Tuple[int, ...], m: int) -> int:
        if len(set(tab)) == 1:
            return 0
        best = m
        for i in range(m):
            block = 1 << (m - 1 - i)
            lo, hi = [], []
            for idx, v in enumerate(tab):
                (hi if (idx // block) % 2 else lo).append(v)
            best = min(best, 1 + max(rec(tuple(lo), m - 1), rec(tuple(hi), m - 1)))
        return best

    return rec(table, N)


def sensitivity(table: Sequence[int]) -> int:
    best = 0
    for x in PANTRIES:
        c = 0
        for i in range(N):
            y = list(x)
            y[i] ^= 1
            if table[INDEX[tuple(y)]] != table[INDEX[x]]:
                c += 1
        best = max(best, c)
    return best


def min_cert_size(table: Sequence[int], x: Tuple[int, ...]) -> int:
    target = table[INDEX[x]]
    for size in range(N + 1):
        for S in combinations(range(N), size):
            ok = True
            for y in PANTRIES:
                if all(y[i] == x[i] for i in S) and table[INDEX[y]] != target:
                    ok = False
                    break
            if ok:
                return size
    return N


def cert_complexities(table: Sequence[int]) -> Tuple[int, int]:
    c0 = c1 = 0
    for x in PANTRIES:
        size = min_cert_size(table, x)
        if table[INDEX[x]]:
            c1 = max(c1, size)
        else:
            c0 = max(c0, size)
    return c0, c1


def classify_quick(table: Sequence[int]) -> str:
    if len(set(table)) == 1:
        return f"constant {table[0]}"
    for i in range(N):
        if all(table[INDEX[x]] == x[i] for x in PANTRIES):
            return f"dictator on ingredient {i + 1}"
        if all(table[INDEX[x]] == 1 - x[i] for x in PANTRIES):
            return f"negated dictator on ingredient {i + 1}"
    return "not quick"


def main() -> None:
    print(__doc__)
    dist: Counter[int] = Counter()
    joint: Counter[Tuple[int, int, int]] = Counter()
    quick_names: List[str] = []
    tight = 0

    for table in product((0, 1), repeat=1 << N):
        v = taste_cost(table)
        s = sensitivity(table)
        c0, c1 = cert_complexities(table)

        assert v <= N, "(i) tasting never exceeds cooking"
        assert s <= v, "(ii) sensitivity lower bound"
        assert max(c0, c1) <= v, "(iii) nondeterminism is at least as fast"
        assert v <= c0 * c1 or v == 0, "(iv) certificate product bound"

        dist[v] += 1
        joint[(v, c0, c1)] += 1
        if v <= 1:
            quick_names.append(classify_quick(table))
        if v > 0 and v == c0 * c1:
            tight += 1

    print("=" * 74)
    print("Population distribution of the tasting cost over all 256 dishes")
    print("=" * 74)
    total = sum(dist.values())
    for v in sorted(dist):
        pct = 100.0 * dist[v] / total
        bar = "#" * int(pct / 2)
        tag = "  <-- EVASIVE (V = C)" if v == N else ""
        print(f"  V = {v}: {dist[v]:4d} dishes  ({pct:5.1f}%)  {bar}{tag}")

    print("\n" + "=" * 74)
    print("Quick recipes (V <= 1) are exactly the constants and (negated) dictators")
    print("=" * 74)
    for name in quick_names:
        print("  " + name)
    print(f"  total: {len(quick_names)} dishes, and the theory predicts 2n + 2 = {2*N+2}")
    assert len(quick_names) == 2 * N + 2
    assert all(name != "not quick" for name in quick_names)

    print("\n" + "=" * 74)
    print("Joint distribution of (V, C0, C1); '*' marks a tight product bound")
    print("=" * 74)
    print(f"  {'V':>2s} {'C0':>3s} {'C1':>3s} {'C0*C1':>6s} {'count':>6s}")
    for (v, c0, c1) in sorted(joint):
        star = " *" if v > 0 and v == c0 * c1 else ""
        print(f"  {v:2d} {c0:3d} {c1:3d} {c0*c1:6d} {joint[(v, c0, c1)]:6d}{star}")
    print(f"\n  the product bound V = C0*C1 is attained by {tight} of the 256 dishes")

    print("\n" + "=" * 74)
    print(f"Conclusion: {dist[N]} of {total} dishes ({100.0*dist[N]/total:.1f}%) are evasive.")
    print("Almost every conceivable recipe is a souffle; the ones we cook are the")
    print("vanishing minority that admits a shortcut.")
    print("=" * 74)


if __name__ == "__main__":
    main()

