function SENSITIVITY-LOWER-BOUND(f, n):
    best <- 0; witness <- (0,...,0); pivots <- empty
    for each pantry x in {0,1}^n:
        here <- empty list
        base <- f(x)
        for i in 1..n:
            y <- x with coordinate i flipped
            if f(y) != base: append i to here
        if |here| > best:
            best <- |here|; witness <- x; pivots <- here
    return (best, witness, pivots)              # best <= V(f), certified

function IS-EVASIVE(f, n):
    return SENSITIVITY-LOWER-BOUND(f, n).best = n

function IS-CERTIFICATE(f, x, S):
    target <- f(x)
    for each pantry y agreeing with x on S:
        if f(y) != target: return false
    return true

function MIN-CERTIFICATE(f, x):
    forced <- { i : flipping coordinate i of x changes f(x) }   # pivotal set
    optional <- all coordinates not in forced
    for size = 0, 1, ..., |optional|:
        for each subset T of optional with |T| = size:
            S <- forced union T
            if IS-CERTIFICATE(f, x, S): return S
    return all coordinates

function CERTIFICATE-COMPLEXITIES(f, n):
    C0 <- 0; C1 <- 0
    for each pantry x:
        s <- |MIN-CERTIFICATE(f, x)|
        if f(x) = 1 then C1 <- max(C1, s) else C0 <- max(C0, s)
    return (C0, C1)

function BUILD-PRODUCT-TASTER(f, n):
    return BUILD((-1, ..., -1))

function BUILD(a):                       # a is the current partial pantry
    V <- { f(x) : x a completion of a }
    if |V| = 1: return Leaf(the unique element of V)
    good <- any completion x of a with f(x) = 1
    S <- MIN-CERTIFICATE(f, good) restricted to coordinates still unknown in a
    if S is empty: S <- { any unknown coordinate }      # defensive
    return PROBE-BLOCK(a, S)

function PROBE-BLOCK(a, S):
    if S is empty: return BUILD(a)
    i <- first element of S; rest <- S minus i
    lo <- PROBE-BLOCK(a with a[i] := 0, rest)
    hi <- PROBE-BLOCK(a with a[i] := 1, rest)
    return Probe(i, lo, hi)

# depth(result) <= C0(f) * C1(f), by the overlap lemma

